// Compile-time contract between the UI's API types (src/api.ts) and the server's OpenAPI schema
// (src/api-types.gen.ts, generated by `npm run gen:api`). `tsc -b` fails if the UI reads a field the
// API does not return, or reads it with an incompatible type. The UI may narrow a string to a union.
import type { components } from "./api-types.gen";
import type * as UI from "./api";

type S = components["schemas"];
type Widen<T> = T extends string ? string : T extends number ? number : T extends boolean ? boolean
  : T extends (infer U)[] ? Widen<U>[] : T extends object ? { [K in keyof T]: Widen<T[K]> } : T;
type FieldOk<U, A> = [Widen<NonNullable<U>>] extends [Widen<NonNullable<A>>] ? true : false;
type Covered<UIType, ApiType> = {
  [K in keyof UIType]-?: K extends keyof ApiType ? (FieldOk<UIType[K], ApiType[K]> extends true ? true : ["type mismatch", K]) : ["missing from API", K];
};
type Ok<T> = T[keyof T] extends true ? true : T[keyof T];
type Expect<T extends true> = T;

export type Contract = [
  Expect<Ok<Covered<UI.Me, S["MeOut"]>>>,
  Expect<Ok<Covered<UI.Conversation, S["ConversationOut"]>>>,
  Expect<Ok<Covered<UI.Message, S["MessageOut"]>>>,
  Expect<Ok<Covered<UI.Task, S["TaskOut"]>>>,
  Expect<Ok<Covered<UI.Notification, S["NotificationOut"]>>>,
  Expect<Ok<Covered<UI.Approval, S["ApprovalOut"]>>>,
  Expect<Ok<Covered<UI.Action, S["ActionOut"]>>>,
  Expect<Ok<Covered<UI.Connector, S["ConnectorOut"]>>>,
  Expect<Ok<Covered<UI.Connection, S["ConnectionOut"]>>>,
  Expect<Ok<Covered<UI.Automation, S["AutomationOut"]>>>,
  Expect<Ok<Covered<UI.Occurrence, S["OccurrenceOut"]>>>,
  Expect<Ok<Covered<UI.BrowserSession, S["SessionOut"]>>>,
  Expect<Ok<Covered<UI.ExportInfo, S["ExportOut"]>>>,
  Expect<Ok<Covered<UI.ConnectionRequest, S["ConnectionRequestOut"]>>>,
  Expect<Ok<Covered<UI.Skill, S["SkillOut"]>>>,
  Expect<Ok<Covered<UI.Share, S["ShareOut"]>>>,
];
